CREATE OR REPLACE FUNCTION public.restore_settings_version(_version uuid,_expected jsonb,_value jsonb,_actor uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE h public.settings_versions; current_row jsonb; current_value jsonb; restored uuid; BEGIN IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO h FROM public.settings_versions WHERE id=_version; IF NOT FOUND OR h.source NOT IN ('site_settings','ai_assistant_settings','contact_settings') THEN RAISE EXCEPTION 'Missing version'; END IF; EXECUTE format('SELECT to_jsonb(s) FROM public.%I s WHERE id=true FOR UPDATE',h.source) INTO current_row; current_value=public.settings_section_value(h.source,h.section,current_row); IF current_value IS DISTINCT FROM _expected THEN RAISE EXCEPTION 'settingsConflict'; END IF; IF public.settings_section_value(h.source,h.section,_value) IS DISTINCT FROM _value OR _value IS DISTINCT FROM h.previous_value THEN RAISE EXCEPTION 'Invalid restore'; END IF; IF _value='{}'::jsonb THEN RAISE EXCEPTION 'No previous value'; END IF; IF h.section='ai' THEN IF current_row->>'api_key' IS NOT NULL AND split_part(current_row->>'base_url','/',3) IS DISTINCT FROM split_part(_value->>'base_url','/',3) THEN RAISE EXCEPTION 'errAiKeyOrigin'; END IF; END IF; IF current_value=_value THEN INSERT INTO public.settings_versions(section,source,actor_id,actor_label,previous_value,new_value,restored_from) VALUES(h.section,h.source,_actor,'',current_value,_value,_version) RETURNING id INTO restored; ELSE EXECUTE format('UPDATE public.%I SET %s, updated_at=now() WHERE id=true',h.source,(SELECT string_agg(format('%I=(jsonb_populate_record(NULL::public.%I,$1)).%I',key,h.source,key),',') FROM jsonb_object_keys(_value) AS key)) USING _value; SELECT id INTO restored FROM public.settings_versions WHERE source=h.source AND section=h.section ORDER BY created_at DESC,id DESC LIMIT 1; UPDATE public.settings_versions SET actor_id=_actor,actor_label='',restored_from=_version WHERE id=restored; END IF; INSERT INTO public.admin_activity(actor_id,actor_email,action,target) VALUES(_actor,'','settings.restore',h.section); RETURN restored; END $$;
REVOKE ALL ON FUNCTION public.restore_settings_version(uuid,jsonb,jsonb,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.restore_settings_version(uuid,jsonb,jsonb,uuid) TO service_role;
COMMENT ON FUNCTION public.restore_settings_version(uuid,jsonb,jsonb,uuid) IS 'Verified admin server only; row-lock compare-and-swap; does not restore or move credentials; every restore creates audit history.';